targets.original_sql:
SELECT
  COUNT(DISTINCT CONCAT(account_name, '-', playlist_name)) AS "Playlists"
FROM spotify_followers;

targets.duckdb_sql:
select
  count(distinct concat(account_name, '-', playlist_name)) as "Playlists"
from spotify_followers;

select
  count(*) as "Playlists"
from (
  select
    concat(account_name, '-', playlist_name) as unique_playlist
  from spotify_followers
  group by unique_playlist
  having max(followers) = 0
) as subquery;

